-- The map of MetLife Stadium (Sean, 2026-10-29: the stadium's own level charts), read the same way as the others: each level's
-- sections clockwise by side. We draw our own map; only the numbers come from the charts. The 200 level's b sections on the two
-- sides (201, 226, 202b...) sit behind the a sections, so they are their own ring. Suites and clubs are left off.

update public.ve_venues set layout = '{"field": "football", "ring_m": 950, "levels": [{"level": "100", "name": "100 level", "sides": {"tl": ["106"], "top": ["108", "109", "110", "111C", "112", "113", "114", "115C", "116", "117", "118"], "tr": ["121"], "right": ["123", "124", "126", "128", "129"], "br": ["131", "133"], "bottom": ["134", "135", "137", "139", "140", "142", "143", "144"], "bl": ["146", "148"], "left": ["149", "101", "103", "104"]}}, {"level": "200", "name": "200 level", "sides": {"tl": ["205a", "206a", "207a"], "top": ["208", "209", "210", "211", "212", "213", "215", "216", "217", "218", "219"], "tr": ["220a"], "right": ["221a", "222a", "223", "224a", "225a", "227a", "228a", "229", "230a"], "br": ["231a", "232a"], "bottom": ["233", "234", "235", "236", "237", "239", "240", "241", "242", "243", "244"], "bl": ["245a", "246a", "247a"], "left": ["248", "249a", "250a", "202a", "203a", "204"]}}, {"level": "200b", "name": "200 level wings (b sections)", "sides": {"tl": ["205b"], "tr": ["222b"], "right": ["224b", "225b", "226", "227b", "228b"], "br": ["230b"], "bl": ["246b"], "left": ["249b", "250b", "201", "202b", "203b"]}}, {"level": "300", "name": "300 level", "sides": {"tl": ["306"], "top": ["307", "308", "309", "310", "311", "312", "313", "314", "315", "316", "317", "318", "319"], "tr": ["320", "321"], "right": ["322", "323", "324", "325", "326", "327", "328", "329", "330"], "br": ["331", "332"], "bottom": ["333", "334", "335", "336", "337", "338", "339", "340", "341", "342", "343", "344", "345"], "bl": ["346", "347"], "left": ["348", "349", "350", "301", "302", "303", "304", "305"]}}]}'::jsonb where slug = 'metlife-stadium';
